const RewardCountUp = ({ value = 0, delay = 0 }) => {
  const targetRef = useRef(null);
  if (targetRef.current === null) {
    targetRef.current = Math.max(0, Math.round(Number(value) || 0));
  }
  const target = targetRef.current;
  const [displayValue, setDisplayValue] = useState(0);

  useEffect(() => {
    let frameId = null;
    const timerId = setTimeout(() => {
      const startTime = typeof performance !== 'undefined' ? performance.now() : Date.now();
      const tick = (now) => {
        const progress = Math.min(1, (now - startTime) / 720);
        const eased = 1 - Math.pow(1 - progress, 3);
        setDisplayValue(Math.round(target * eased));
        if (progress < 1 && typeof requestAnimationFrame === 'function') {
          frameId = requestAnimationFrame(tick);
        }
      };

      if (typeof requestAnimationFrame === 'function') {
        frameId = requestAnimationFrame(tick);
      } else {
        setDisplayValue(target);
      }
    }, delay);

    return () => {
      clearTimeout(timerId);
      if (frameId && typeof cancelAnimationFrame === 'function') cancelAnimationFrame(frameId);
    };
  }, [delay, target]);

  return <>{displayValue.toLocaleString('zh-CN')}</>;
};

const buildBattleVictoryDisplaySnapshot = ({ enemyName, isTrainer, rewardSummary }) => {
  const rewards = normalizeBattleRewardSummary(rewardSummary);
  const participantText = rewards.participantCount > 1
    ? `${rewards.participantCount} 只宝可梦平分`
    : '出战宝可梦获得';
  const primaryRewardItems = [
    {
      key: 'gold',
      className: 'battle-victory-reward--gold',
      icon: 'fa-coins',
      label: '金币',
      value: rewards.gold,
      meta: '已加入钱包',
      delay: 980
    },
    {
      key: 'exp',
      className: 'battle-victory-reward--exp',
      icon: 'fa-bolt',
      label: '经验',
      value: rewards.exp,
      meta: participantText,
      delay: 1130
    }
  ];
  const itemRewardItems = rewards.items.map((item, index) => ({
    key: `item-${index}-${item.itemName}`,
    icon: 'fa-gift',
    sprite: item.sprite,
    label: item.itemName,
    value: item.quantity,
    delay: 1280 + index * 90
  }));

  return {
    enemyName: typeof enemyName === 'string' && enemyName.length > 0 ? enemyName : '对手',
    isTrainer: Boolean(isTrainer),
    rewards,
    levelUps: rewards.levelUps || [],
    unlocks: rewards.unlocks || [],
    ecologySurvey: rewards.ecologySurvey || null,
    primaryRewardItems,
    itemRewardItems,
    rewardDetailCount: primaryRewardItems.length + itemRewardItems.length + (rewards.unlocks?.length || 0) + (rewards.levelUps?.length || 0) + (rewards.ecologySurvey ? 1 : 0)
  };
};

const BATTLE_METER_TONES = {
  hpHealthy: {
    className: 'battle-meter-fill-hp-healthy',
    color: '#00e676',
    from: '#00e676',
    to: '#1de9b6'
  },
  hpWarning: {
    className: 'battle-meter-fill-hp-warning',
    color: '#facc15',
    from: '#facc15',
    to: '#f97316'
  },
  hpCritical: {
    className: 'battle-meter-fill-hp-critical',
    color: '#ef4444',
    from: '#ef4444',
    to: '#dc2626'
  },
  mp: {
    className: '',
    color: '#29b6f6',
    from: '#29b6f6',
    to: '#4fc3f7'
  },
  exp: {
    className: '',
    color: '#d500f9',
    from: '#d500f9',
    to: '#ffb300'
  }
};

const getBattleMeterTone = (variant, percent) => {
  if (variant === 'mp') return BATTLE_METER_TONES.mp;
  if (variant === 'exp') return BATTLE_METER_TONES.exp;
  if (percent <= 20) return BATTLE_METER_TONES.hpCritical;
  if (percent <= 50) return BATTLE_METER_TONES.hpWarning;
  return BATTLE_METER_TONES.hpHealthy;
};

const BattleMeter = ({ label, current, max, variant = 'hp', showValue = true }) => {
  const safeMax = Number.isFinite(max) && max > 0 ? max : 1;
  const rawCurrent = Number.isFinite(current) ? current : 0;
  const safeCurrent = Math.max(0, Math.min(safeMax, rawCurrent));
  const percent = Math.max(0, Math.min(100, safeCurrent / safeMax * 100));
  const previousPercentRef = useRef(percent);
  const [chipPercent, setChipPercent] = useState(percent);
  const variantClass = {
    hp: 'battle-meter-fill-hp',
    mp: 'battle-meter-fill-mp',
    exp: 'battle-meter-fill-exp'
  }[variant] || 'battle-meter-fill-hp';
  const tone = getBattleMeterTone(variant, percent);
  const fillStyle = {
    width: `${percent}%`,
    '--battle-meter-color': tone.color,
    '--battle-meter-from': tone.from,
    '--battle-meter-to': tone.to
  };

  useEffect(() => {
    const previousPercent = previousPercentRef.current;
    previousPercentRef.current = percent;
    if (variant !== 'hp' || percent >= previousPercent) {
      setChipPercent(percent);
      return undefined;
    }
    setChipPercent(previousPercent);
    const timer = window.setTimeout(() => setChipPercent(percent), 110);
    return () => window.clearTimeout(timer);
  }, [percent, variant]);

  return (
    <div className={`battle-meter-row battle-meter-row-${variant}`}>
      <div className="flex items-center justify-between gap-2 text-[10px] font-black uppercase text-white/70">
        <span>{label}</span>
        {showValue && <span className="text-white/90">{safeCurrent}/{safeMax}</span>}
      </div>
      <div
        className={`battle-meter-track battle-meter-track-${variant}`}
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={safeMax}
        aria-valuenow={safeCurrent}
      >
        {variant === 'hp' && (
          <div className="battle-meter-damage-chip" style={{ width: `${chipPercent}%` }} aria-hidden="true" />
        )}
        <div
          className={`battle-meter-fill ${variantClass} ${tone.className} ${percent <= 0 ? 'battle-meter-fill-empty' : ''}`}
          style={fillStyle}
        />
      </div>
    </div>
  );
};

const STAT_STAGE_ICONS = { atk: '⚔', def: '🛡', spAtk: '✨', spDef: '💎', spd: '⚡' };
const STAT_STAGE_LABELS = { atk: '攻', def: '防', spAtk: '特攻', spDef: '特防', spd: '速' };

const BattleStatStages = ({ statStages }) => {
  if (!statStages) return null;
  const entries = Object.entries(statStages).filter(([, v]) => v !== 0);
  if (entries.length === 0) return null;
  return (
    <div className="flex flex-wrap gap-0.5 mt-0.5">
      {entries.map(([stat, stage]) => (
        <span
          key={stat}
          title={`${STAT_STAGE_LABELS[stat] || stat} ${stage > 0 ? '+' : ''}${stage}`}
          className={`inline-flex items-center gap-0.5 rounded px-1 py-0 text-[9px] font-black leading-tight border ${
            stage > 0
              ? 'bg-emerald-500/25 border-emerald-400/50 text-emerald-200'
              : 'bg-red-500/25 border-red-400/50 text-red-200'
          }`}
          style={{ animation: 'battleStatStagePop 0.35s cubic-bezier(.36,1.56,.64,1) both' }}
        >
          <span className="opacity-80">{STAT_STAGE_ICONS[stat] || stat}</span>
          <span>{stage > 0 ? `+${stage}` : stage}</span>
        </span>
      ))}
    </div>
  );
};

const BattleHudCard = ({ mon, stats, hint, align = 'left', playerGold = null, showMp = true, showExp = false, className = '', partyBalls = null }) => {
  const expMax = Number.isFinite(mon.expToNextLevel) ? mon.expToNextLevel : 1;
  const layoutClass = className || (align === 'right' ? 'battle-hud-enemy' : 'battle-hud-player');
  const statusNotes = getBattleStatusNotes(mon);
  const visibleStatusNotes = statusNotes.slice(0, 2);
  const hiddenStatusCount = Math.max(0, statusNotes.length - visibleStatusNotes.length);
  const statusSummaryLabel = statusNotes
    .map((note) => `${note.fullLabel}：${note.hint}`)
    .join('；');
  const hintMeta = hint || { text: '', className: '' };
  // 低血量外框反馈：阈值与 BattleMeter 的 HP 染色保持一致（≤20% 危急 / ≤50% 警戒）。
  const hpPercent = stats.maxHp > 0 ? stats.currentHp / stats.maxHp * 100 : 100;
  const hpDangerClass = stats.currentHp <= 0
    ? ''
    : hpPercent <= 20
      ? 'battle-glass-card--critical'
      : hpPercent <= 50
        ? 'battle-glass-card--warning'
        : '';
  return (
    <div className={`battle-glass-card ${layoutClass} ${hpDangerClass}`}>
      <div className="flex items-start justify-between gap-1.5">
        <div className="min-w-0">
          <div className="flex min-w-0 items-center gap-1.5">
            <div className="truncate text-sm font-black leading-none text-white drop-shadow">{mon.name}</div>
          </div>
          <BattleStatStages statStages={mon.statStages} />
          <div className="mt-1 flex flex-wrap gap-1">
            {mon.type2 && <TypeBadge type={mon.type2} small />}
            <TypeBadge type={mon.type} small />
          </div>
        </div>
        <div className="shrink-0 rounded-full border border-yellow-200/60 bg-yellow-300/20 px-2 py-0.5 text-[11px] font-black text-yellow-100">
          Lv.{mon.level}
        </div>
      </div>

      <div className="mt-2 space-y-1.5">
        <BattleMeter label="HP" current={stats.currentHp} max={stats.maxHp} variant="hp" />
        {showMp && <BattleMeter label="MP" current={stats.currentMp} max={stats.maxMp} variant="mp" />}
        {showExp && <BattleMeter label="EXP" current={mon.currentExp || 0} max={expMax} variant="exp" />}
      </div>

      {statusNotes.length > 0 && (
        <div
          className="battle-status-note"
          aria-label={`${mon.name}的异常状态：${statusSummaryLabel}`}
          title={statusSummaryLabel}
        >
          {visibleStatusNotes.map((note) => (
            <span key={note.key || note.fullLabel} className="battle-status-note__item" title={`${note.fullLabel}：${note.hint}`}>
              <span className={`battle-status-badge battle-status-badge--hud ${note.className}`}>
                {note.displayLabel || note.fullLabel}
              </span>
            </span>
          ))}
          {hiddenStatusCount > 0 && (
            <span className="battle-status-note__more" title={statusSummaryLabel}>+{hiddenStatusCount}</span>
          )}
        </div>
      )}

      <div className="battle-hud-footer">
        <span className={`battle-hud-hint ${hintMeta.className}`}>{hintMeta.text}</span>
        {partyBalls}
        {playerGold !== null && (
          <span className="inline-flex items-center gap-1 rounded-full bg-yellow-300/20 px-1.5 py-0.5 text-[10px] font-black text-yellow-100">
            <i className="fa-solid fa-coins text-yellow-300"></i>
            {playerGold}
          </span>
        )}
      </div>
    </div>
  );
};

const BattleActionButton = ({ label, icon, variant, disabled, onClick, title = '', note = '', locked = false }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    title={title}
    className={`battle-action-button battle-action-${variant} ${locked ? 'battle-action-button--locked' : ''}`}
  >
    <i className={`fa-solid ${icon}`}></i>
    <span className="battle-action-button__content">
      <span className="battle-action-button__label">{label}</span>
      {note ? <span className="battle-action-button__note">{note}</span> : null}
    </span>
  </button>
);

const MonsterSprite = ({ monster, isBack = false, animate = false, sizeMultiplier = 1, isBattleContext = false }) => {
  if (!monster) return null;
  const displayMonster = getBattleDisplayMonster(monster);
  const spriteUrl = isBack ? displayMonster.backSprite : displayMonster.sprite;
  const fallbackUrl = displayMonster.fallbackSprite || spriteUrl;
  const [resolvedSpriteUrl, setResolvedSpriteUrl] = useState(spriteUrl);

  useEffect(() => {
    setResolvedSpriteUrl(spriteUrl);
  }, [spriteUrl]);

  // 定义基础单位尺寸。
  // 战斗场景：基础约96-112px（根据反馈已显著增大）
  // 启动页：基础64px
  const baseImageUnit = isBattleContext ? BATTLE_SPRITE_IMAGE_BASE_UNIT : LAUNCH_SPRITE_IMAGE_BASE_UNIT;
  const baseContainerUnit = isBattleContext ? BATTLE_SPRITE_CONTAINER_BASE_UNIT : LAUNCH_SPRITE_CONTAINER_BASE_UNIT;

  // 使用内联样式而非动态类名，以确保任何倍数都能准确渲染像素
  const containerPx = baseContainerUnit * sizeMultiplier;
  const imagePx = baseImageUnit * sizeMultiplier;

  return (
    <div 
      className={`relative flex items-center justify-center ${animate ? 'animate-bounce' : ''}`}
      style={{ width: `${containerPx}px`, height: `${containerPx}px` }}
    >
      <img
        src={resolvedSpriteUrl}
        alt={displayMonster.name}
        className="object-contain transition-transform duration-300"
        onError={() => {
          if (resolvedSpriteUrl !== fallbackUrl) setResolvedSpriteUrl(fallbackUrl);
        }}
        style={{ 
          width: `${imagePx}px`, 
          height: `${imagePx}px`, 
          imageRendering: 'auto',
          transform: isBack ? 'scaleX(-1)' : 'none'
        }} 
      />
      {/* 底部投影 */}
      <div 
        className="absolute bottom-2 h-3 bg-black/30 rounded-full blur-sm"
        style={{ width: `${imagePx * 0.8}px` }}
      ></div>
    </div>
  );
};

const CaptureSequenceOverlay = ({ show, data, onComplete, paused = false }) => {
  const [finishing, setFinishing] = useState(false);
  const [awaitingConfirm, setAwaitingConfirm] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const [capturingInBall, setCapturingInBall] = useState(false);
  const mountedRef = useRef(false);
  const confirmCompleteTimerRef = useRef(null);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      if (confirmCompleteTimerRef.current) {
        window.clearTimeout(confirmCompleteTimerRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (!show || !data || paused) return undefined;

    if (confirmCompleteTimerRef.current) {
      window.clearTimeout(confirmCompleteTimerRef.current);
      confirmCompleteTimerRef.current = null;
    }
    setFinishing(false);
    setAwaitingConfirm(false);
    setConfirming(false);
    setCapturingInBall(false);
    const finishDelay = data.success ? 6100 : 4700;
    const completeDelay = data.success ? 7900 : 5600;

    const throwTimer = setTimeout(() => gameAudio.playCaptureThrow(), 120);
    const shake1Timer = setTimeout(() => gameAudio.playCaptureShake(), 2500);
    const shake2Timer = setTimeout(() => gameAudio.playCaptureShake(), 3450);
    const shake3Timer = setTimeout(() => gameAudio.playCaptureShake(), 4350);
    const resultSfxTimer = setTimeout(() => {
      if (data.success) {
        gameAudio.playCaptureSuccess();
      } else {
        gameAudio.playCaptureFail();
      }
    }, data.success ? 5100 : 4850);
    const finishTimer = setTimeout(() => setFinishing(true), finishDelay);
    const confirmReadyTimer = data.success
      ? setTimeout(() => setAwaitingConfirm(true), completeDelay)
      : null;
    const completeTimer = data.success
      ? null
      : setTimeout(() => onComplete?.(data), completeDelay);

    return () => {
      clearTimeout(throwTimer);
      clearTimeout(shake1Timer);
      clearTimeout(shake2Timer);
      clearTimeout(shake3Timer);
      clearTimeout(resultSfxTimer);
      clearTimeout(finishTimer);
      if (confirmReadyTimer) clearTimeout(confirmReadyTimer);
      if (completeTimer) clearTimeout(completeTimer);
      if (confirmCompleteTimerRef.current) {
        window.clearTimeout(confirmCompleteTimerRef.current);
        confirmCompleteTimerRef.current = null;
      }
    };
  }, [show, data, onComplete, paused]);

  if (!show || !data) return null;

  const success = Boolean(data.success);
  const resultText = success
    ? '已加入队伍'
    : `${data.pokemonName} 挣脱了精灵球`;
  const catchRateLabel = Number.isFinite(Number(data.catchRate))
    ? `${Math.round(Number(data.catchRate))}%`
    : null;
  const handleConfirmCapture = () => {
    if (!success || !awaitingConfirm || confirming) return;
    setConfirming(true);
    setCapturingInBall(true);
    gameAudio.playUiConfirm();
    confirmCompleteTimerRef.current = window.setTimeout(() => {
      confirmCompleteTimerRef.current = null;
      if (!mountedRef.current) return;
      const completion = onComplete?.(data);
      if (completion && typeof completion.finally === 'function') {
        completion.finally(() => {
          if (mountedRef.current) setConfirming(false);
        });
      } else if (mountedRef.current) {
        setConfirming(false);
      }
    }, 1120);
  };

  return (
    <div
      className={`capture-sequence-overlay ${success ? 'capture-success-mode' : 'capture-fail-mode'} ${finishing ? 'capture-finishing' : ''} ${awaitingConfirm ? 'capture-awaiting-confirm' : ''} ${capturingInBall ? 'capture-confirming-ball' : ''}`}
      aria-live="assertive"
    >
      <div className="capture-cinema-bars" aria-hidden="true">
        <span />
        <span />
      </div>
      <div className="capture-speed-lines" />
      <div className="capture-stage-glow" />
      <div className="capture-victory-rays" aria-hidden="true" />
      <div className="capture-throw-arc" />
      <div className="capture-starfield" aria-hidden="true">
        {Array.from({ length: 24 }, (_, index) => <span key={index} />)}
      </div>

      <div className="capture-target-wrap">
        <div className="capture-target-ring" />
        <img
          src={data.pokemonSprite}
          alt={data.pokemonName}
          className="capture-target-sprite"
          onError={handlePokemonImageError}
        />
        <div className="capture-target-name">
          <span>{data.pokemonName}</span>
          {data.pokemonLevel ? <small>Lv.{data.pokemonLevel}</small> : null}
        </div>
      </div>

      <div className="capture-energy-beam">
        <span />
        <span />
        <span />
      </div>

      <div className="capture-ball-stage">
        <div className="capture-ball-shadow" />
        <div className="capture-orbit-field" aria-hidden="true">
          <span />
          <span />
          <span />
        </div>
        <div className="capture-seal-ring capture-seal-ring--outer" />
        <div className="capture-seal-ring capture-seal-ring--middle" />
        <div className="capture-seal-ring capture-seal-ring--inner" />
        <img
          src={data.ballSprite || POKEBALLS.pokeball_basic.sprite}
          alt={data.ballName || '精灵球'}
          className="capture-ball-image"
          onError={handleItemImageError}
        />
        <div className="capture-ball-lock" />
        <div className="capture-ball-flash" />
      </div>

      {success && (
        <div className="capture-success-burst" aria-hidden="true">
          <i />
          <i />
          <i />
          <i />
        </div>
      )}

      {success && (
        <div className="capture-success-sparkles" aria-hidden="true">
          {Array.from({ length: 18 }, (_, index) => <span key={index} />)}
        </div>
      )}

      <div className="capture-tension-panel">
        <div className="capture-tension-title">{data.ballName || '精灵球'}正在摇晃...</div>
        <div className="capture-tension-dots" aria-hidden="true">
          <span />
          <span />
          <span />
        </div>
      </div>

      <div className="capture-result-card">
        {!success && <div className="capture-result-kicker">捕捉结果</div>}
        {!success && <div className="capture-result-title">差一点！</div>}
        {success && (
          <div className="capture-result-hero">
            <div className="capture-result-hero__aura" />
            <img
              src={data.pokemonSprite}
              alt={data.pokemonName}
              className="capture-result-hero__sprite"
              onError={handlePokemonImageError}
            />
            <div className="capture-result-hero__ball">
              <img
                src={data.ballSprite || POKEBALLS.pokeball_basic.sprite}
                alt={data.ballName || '精灵球'}
                onError={handleItemImageError}
              />
            </div>
            <div className="capture-result-hero__flash" aria-hidden="true" />
          </div>
        )}
        {success && (
          <div className="capture-result-nameplate">
            <strong>{data.pokemonName}</strong>
            <div>
              {data.pokemonLevel ? <span>Lv.{data.pokemonLevel}</span> : null}
              {catchRateLabel ? <span>捕获率 {catchRateLabel}</span> : null}
            </div>
          </div>
        )}
        <div className="capture-result-text">{resultText}</div>
        {success && (
          <button
            type="button"
            className="capture-result-confirm"
            onClick={handleConfirmCapture}
            disabled={!awaitingConfirm || confirming || capturingInBall}
          >
            <i className="fa-solid fa-check" aria-hidden="true" />
            <span>{capturingInBall ? '收进球里' : '确认'}</span>
          </button>
        )}
      </div>
    </div>
  );
};

